document.addEventListener("DOMContentLoaded", function () {
  if (window.frappe && typeof frappe.call === "function") {
    console.log("✅ DOM dan Frappe siap");

    frappe.call("custom_ui.custom_ui.doctype.ui_theme.ui_theme.get_active_theme")
      .then(r => {
        const data = r.message;
        console.log("🌈 Tema aktif:", data);

        const variables = data.variables || {};
        const root = document.documentElement;
        Object.keys(variables).forEach(key => {
          root.style.setProperty(key, variables[key]);
        });

        console.log("✅ Tema berhasil diterapkan di global system");
      })
      .catch(err => {
        console.error("❌ Gagal memuat tema:", err);
      });
  } else {
    console.warn("⚠️ frappe.call belum tersedia. Tunggu hingga Frappe selesai loading.");
  }
});
